package com.pousadamarealta.messaging;

import com.pousadamarealta.domain.MessageStatus;

import java.util.ArrayList;
import java.util.List;

public class MessageProcessor {
    private final List<MessageRule> rules;
    private final boolean testMode;

    public MessageProcessor(boolean testMode) {
        this.testMode = testMode;
        this.rules = List.of(
            new EmailValidationRule(),
            new TestModeRule(),
            new ArchiveCopyRule()
        );
    }

    public List<ProcessedMessage> process(OutgoingMessage message) {
        List<ProcessedMessage> results = new ArrayList<>();
        ProcessedMessage primaryMessage = null;

        for (MessageRule rule : rules) {
            List<ProcessedMessage> ruleResults = rule.apply(message, testMode);

            for (ProcessedMessage processed : ruleResults) {
                if (processed.getStatus() == MessageStatus.BLOCKED) {
                    return List.of(processed);
                }

                if (primaryMessage == null) {
                    primaryMessage = processed;
                } else {
                    results.add(processed);
                }
            }
        }

        if (primaryMessage == null) {
            primaryMessage = new ProcessedMessage(
                message.getChannel(),
                message.getTo(),
                message.getSubject(),
                message.getBody(),
                MessageStatus.SENT
            );
        }

        List<ProcessedMessage> finalResults = new ArrayList<>();
        finalResults.add(primaryMessage);
        finalResults.addAll(results);

        return finalResults;
    }
}

