                pm.getChannel(),
                pm.getTo(),
                pm.getSubject(),
                pm.getBody(),
                pm.getStatus()
            );
            messages.add(message);
        }
    }

    public List<Message> getAllMessages() {
        return List.copyOf(messages);
    }
}

